from pathlib import Path
import base64
import gzip
import subprocess

PATCH_B64 = ""

patch = gzip.decompress(base64.b64decode(PATCH_B64))
patch_path = Path(".git/phase2-generator-context.patch")
patch_path.write_bytes(patch)
subprocess.run(["git", "apply", "--whitespace=error-all", str(patch_path)], check=True)
print("GenerationContext phase 2 patch applied")
